/** Generated by scaffold-crud-pages. Query hooks for Subscriptions.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchSubscriptionsList,
  fetchSubscriptionsById,
  createSubscriptions,
  updateSubscriptions,
  deleteSubscriptions,
  type FetchSubscriptionsListParams,
} from '~/services/httpServices/subscriptionsService';
import type { CreateSubscriptionsRequest, UpdateSubscriptionsRequest } from '~/types/subscriptions';

const DOMAIN = 'subscriptions';

export function useSubscriptionsList(params?: FetchSubscriptionsListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchSubscriptionsList(params),
  });
}

export function useSubscriptions(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchSubscriptionsById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateSubscriptions() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateSubscriptionsRequest) => createSubscriptions(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateSubscriptions() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateSubscriptionsRequest }) =>
      updateSubscriptions(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteSubscriptions() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteSubscriptions(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
